window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[81]={"8100":{"example:8100:exzh":"Looking around in all directions, a beautiful view spreads out.","example:8100:exzh2":"Let's contact friends near and far and go out together.","example:8100:exzh3":"This room has windows on all four sides.","example:8100:exzh4":"The wind comes blowing in from all directions.","example:8100:exzh5":"We scattered in every direction."},"8101":{"example:8101:exzh":"We got ready in preparation for an enemy attack.","example:8101:exzh2":"Because of the approaching typhoon, school was canceled.","example:8101:exzh3":"He sensed the crisis that was about to strike.","example:8101:exzh4":"The town fell silent because of the approaching storm.","example:8101:exzh5":"In preparation for the attack, we checked the evacuation site."},"8102":{"example:8102:exzh":"We need to get to the bottom of what really happened in the case.","example:8102:exzh2":"The researchers are working hard to get to the bottom of the problem.","example:8102:exzh3":"He spent a lot of time investigating the question.","example:8102:exzh4":"Research into new technology is progressing.","example:8102:exzh5":"We must investigate the cause."},"8104":{"example:8104:exzh":"I dropped my guitar pick somewhere.","example:8104:exzh2":"I want to try out all kinds of picks.","example:8104:exzh3":"This pick is thin and soft.","example:8104:exzh4":"Some people play with their fingers instead of using a pick.","example:8104:exzh5":"I bought three new picks at the music store."},"8105":{"example:8105:exzh":"We're going on a trip tomorrow.","example:8105:exzh2":"Our family gets along well.","example:8105:exzh3":"We went out together to have fun.","example:8105:exzh4":"We've been friends since way back.","example:8105:exzh5":"Let's be the ones to solve this problem."},"8106":{"example:8106:exzh":"He firmly stated his opposing view.","example:8106:exzh2":"You should face it with a firm attitude.","example:8106:exzh3":"The problem needs a firm solution.","example:8106:exzh4":"She firmly rejected that proposal.","example:8106:exzh5":"We must stand firmly united."},"8107":{"example:8107:exzh":"Horses are running around the meadow.","example:8107:exzh2":"He keeps a horse.","example:8107:exzh3":"Horses can run fast.","example:8107:exzh4":"Looking after a horse is a lot of work.","example:8107:exzh5":"She went out together with the horse.","grammar:8107:ex:trans":"The horse is running all over the meadow.","grammar:8107:ex:structure":"ウマが草原を＋駆け回っている","grammar:8107:ex:explain":"Here 「を」 marks the space that is moved through, so 「草原を駆け回る」 means running all over the meadow. 「駆け回る」 is a compound verb (駆ける＋回る) meaning to run around. The one doing the running, 「ウマ」 (horse), takes 「が」. 「駆け回っている」 uses 「〜ている」 to show the action is in progress. Using 「を」 before this kind of motion verb to mark the space traversed is an important particle usage in Japanese.","grammar:8107:ex:words:0:zh":"horse","grammar:8107:ex:words:0:pos":"noun","grammar:8107:ex:words:1:zh":"(nominative)","grammar:8107:ex:words:1:pos":"particle","grammar:8107:ex:words:2:zh":"meadow","grammar:8107:ex:words:2:note":"そうげん","grammar:8107:ex:words:2:pos":"noun","grammar:8107:ex:words:3:zh":"(place passed through)","grammar:8107:ex:words:3:pos":"particle","grammar:8107:ex:words:4:zh":"run around","grammar:8107:ex:words:4:note":"かけまわって (te-form)","grammar:8107:ex:words:4:pos":"verb","grammar:8107:ex:words:5:zh":"(action in progress)","grammar:8107:ex:words:5:pos":"auxiliary verb","grammar:8107:ex:points:0":"〜を＋motion verb: を marks the space passed through (草原を駆け回る = run around the meadow)","grammar:8107:ex:points:1":"Compound verb 「駆け回る」 = 駆ける＋回る (run around)","grammar:8107:ex2:trans":"He keeps a horse.","grammar:8107:ex2:structure":"ウマを＋飼っています","grammar:8107:ex2:words:0:zh":"he","grammar:8107:ex2:words:0:note":"かれ","grammar:8107:ex2:words:0:pos":"pronoun","grammar:8107:ex2:words:1:zh":"(topic)","grammar:8107:ex2:words:1:pos":"particle","grammar:8107:ex2:words:2:zh":"horse","grammar:8107:ex2:words:2:pos":"noun","grammar:8107:ex2:words:3:zh":"(object marker)","grammar:8107:ex2:words:3:pos":"particle","grammar:8107:ex2:words:4:zh":"keeping (an animal)","grammar:8107:ex2:words:4:note":"かって (te-form with っ)","grammar:8107:ex2:words:4:pos":"verb","grammar:8107:ex2:words:5:zh":"(ongoing state)","grammar:8107:ex2:words:5:pos":"auxiliary verb","grammar:8107:ex2:points:0":"〜ている: here it shows a continuing state (keeping)","grammar:8107:ex2:points:1":"「ウマを飼う」 = keep a horse","grammar:8107:ex3:trans":"Horses can run fast.","grammar:8107:ex3:structure":"速く走ることが＋できる","grammar:8107:ex3:words:0:zh":"horse","grammar:8107:ex3:words:0:pos":"noun","grammar:8107:ex3:words:1:zh":"(topic)","grammar:8107:ex3:words:1:pos":"particle","grammar:8107:ex3:words:2:zh":"fast","grammar:8107:ex3:words:2:note":"はやく (adverbial form)","grammar:8107:ex3:words:2:pos":"adjective","grammar:8107:ex3:words:3:zh":"ran","grammar:8107:ex3:words:3:note":"はしる","grammar:8107:ex3:words:3:pos":"verb","grammar:8107:ex3:words:4:zh":"(object of ability)","grammar:8107:ex3:words:4:pos":"formal noun","grammar:8107:ex3:words:5:zh":"(nominative)","grammar:8107:ex3:words:5:pos":"particle","grammar:8107:ex3:words:6:zh":"be able to","grammar:8107:ex3:words:6:pos":"verb","grammar:8107:ex3:points:0":"〜ことができる: be able to do 〜 (走ることができる = can run)","grammar:8107:ex3:points:1":"The adjective's adverbial form 「速く」 = quickly; it modifies a verb","grammar:8107:ex4:trans":"Looking after a horse is hard work.","grammar:8107:ex4:structure":"ウマの世話は＋大変です","grammar:8107:ex4:words:0:zh":"horse","grammar:8107:ex4:words:0:pos":"noun","grammar:8107:ex4:words:1:zh":"'s","grammar:8107:ex4:words:1:pos":"particle","grammar:8107:ex4:words:2:zh":"look after","grammar:8107:ex4:words:2:note":"せわ","grammar:8107:ex4:words:2:pos":"noun","grammar:8107:ex4:words:3:zh":"(topic)","grammar:8107:ex4:words:3:pos":"particle","grammar:8107:ex4:words:4:zh":"trouble, hardship","grammar:8107:ex4:words:4:note":"たいへん","grammar:8107:ex4:words:4:pos":"na-adjective","grammar:8107:ex4:words:5:zh":"(assertion · polite)","grammar:8107:ex4:words:5:pos":"auxiliary verb","grammar:8107:ex4:points:0":"「〜の世話」 = looking after 〜 (ウマの世話 = looking after a horse)","grammar:8107:ex4:points:1":"「大変だ」 is a na-adjective in polite assertive form","grammar:8107:ex5:trans":"She went out with the horse.","grammar:8107:ex5:structure":"ウマと一緒に＋出かけた","grammar:8107:ex5:words:0:zh":"she","grammar:8107:ex5:words:0:note":"かのじょ","grammar:8107:ex5:words:0:pos":"pronoun","grammar:8107:ex5:words:1:zh":"(topic)","grammar:8107:ex5:words:1:pos":"particle","grammar:8107:ex5:words:2:zh":"horse","grammar:8107:ex5:words:2:pos":"noun","grammar:8107:ex5:words:3:zh":"with (the person you do something together with)","grammar:8107:ex5:words:3:pos":"particle","grammar:8107:ex5:words:4:zh":"together","grammar:8107:ex5:words:4:note":"いっしょに","grammar:8107:ex5:words:4:pos":"adverb","grammar:8107:ex5:words:5:zh":"go out; head out","grammar:8107:ex5:words:5:note":"でかけた","grammar:8107:ex5:words:5:pos":"verb","grammar:8107:ex5:points:0":"〜と一緒に: together with 〜 (ウマと一緒に = together with the horse)","grammar:8107:ex5:points:1":"「出かける」 ichidan (ru-) verb, intransitive (go out)","exam:8107:zh":"At the ranch I saw a horse neighing 「ヒヒーン」.","exam:8107:why":"Japanese uses 「ヒヒーン」 for a horse's neigh, so the correct answer is 「ウマ」. 「牛」 is also common on a ranch, but its moo is usually written 「モー」."},"8108":{"example:8108:exzh":"This string has a lot of tension.","example:8108:exzh2":"Firm, taut skin is a sign of health.","example:8108:exzh3":"I feel the tightness of tension.","example:8108:exzh4":"There was strength in his voice.","example:8108:exzh5":"I've been feeling tense from stress."},"8109":{"example:8109:exzh":"They are thinking seriously about marriage.","example:8109:exzh2":"Marriage isn't just about love.","example:8109:exzh3":"We are enjoying married life.","example:8109:exzh4":"Marriage comes with responsibility.","example:8109:exzh5":"Marriage is a promise between two people."},"8110":{"example:8110:exzh":"I need to apologize to him.","example:8110:exzh2":"It's important to apologize sincerely.","example:8110:exzh3":"I apologized for my mistake.","example:8110:exzh4":"It takes courage to apologize.","example:8110:exzh5":"After I apologized to her, I felt relieved.","grammar:8110:ex:trans":"I need to apologize to him.","grammar:8110:ex:structure":"〜に謝る必要があります","grammar:8110:ex:explain":"The key verb 「謝る（あやまる）」 is an intransitive verb meaning to apologize or make amends, and the person you apologize to is marked with 「に」, so 「彼に謝る」 means to apologize to him. The pattern 「〜必要があります」 expresses that something is necessary: the dictionary form of the verb 「謝る」 is followed by 「必要」, with 「が」 marking the subject. The whole sentence means it is necessary to apologize to him, and the omitted subject is the speaker. Note that the person you apologize to takes 「に」, not 「を」.","grammar:8110:ex:words:0:zh":"he","grammar:8110:ex:words:0:note":"かれ","grammar:8110:ex:words:0:pos":"pronoun","grammar:8110:ex:words:1:zh":"(object)","grammar:8110:ex:words:1:pos":"particle","grammar:8110:ex:words:2:zh":"apology","grammar:8110:ex:words:2:note":"あやまる","grammar:8110:ex:words:2:pos":"verb","grammar:8110:ex:words:3:zh":"necessary","grammar:8110:ex:words:3:note":"ひつよう","grammar:8110:ex:words:3:pos":"noun","grammar:8110:ex:words:4:zh":"(nominative)","grammar:8110:ex:words:4:pos":"particle","grammar:8110:ex:words:5:zh":"there is / are","grammar:8110:ex:words:5:pos":"verb","grammar:8110:ex:points:0":"❗謝る（あやまる）: to apologize, to make amends (intransitive verb; the person you apologize to takes に); 〜に謝る = to apologize to…","grammar:8110:ex:points:1":"彼に謝る: to apologize to him.","grammar:8110:ex2:trans":"It's important to apologize sincerely.","grammar:8110:ex2:structure":"素直に謝ることが大切です","grammar:8110:ex2:words:0:zh":"frank","grammar:8110:ex2:words:0:note":"すなお","grammar:8110:ex2:words:0:pos":"na-adjective","grammar:8110:ex2:words:1:zh":"(made adverbial)","grammar:8110:ex2:words:1:pos":"particle","grammar:8110:ex2:words:2:zh":"apology","grammar:8110:ex2:words:2:note":"あやまる","grammar:8110:ex2:words:2:pos":"verb","grammar:8110:ex2:words:3:zh":"(nominalizer)","grammar:8110:ex2:words:3:pos":"noun","grammar:8110:ex2:words:4:zh":"(nominative)","grammar:8110:ex2:words:4:pos":"particle","grammar:8110:ex2:words:5:zh":"important","grammar:8110:ex2:words:5:note":"たいせつ","grammar:8110:ex2:words:5:pos":"na-adjective","grammar:8110:ex2:words:6:zh":"(polite form)","grammar:8110:ex2:words:6:pos":"copula","grammar:8110:ex2:points:0":"❗素直に: honestly, frankly (素直 + に); 謝る = to apologize.","grammar:8110:ex2:points:1":"素直に謝る: to apologize sincerely.","grammar:8110:ex3:trans":"I apologized for the mistake.","grammar:8110:ex3:structure":"〜を謝った","grammar:8110:ex3:words:0:zh":"the thing I got wrong","grammar:8110:ex3:words:0:note":"まちがえた","grammar:8110:ex3:words:0:pos":"verb","grammar:8110:ex3:words:1:zh":"thing / matter","grammar:8110:ex3:words:1:pos":"noun","grammar:8110:ex3:words:2:zh":"(object marker)","grammar:8110:ex3:words:2:pos":"particle","grammar:8110:ex3:words:3:zh":"apologized","grammar:8110:ex3:words:3:note":"あやまった","grammar:8110:ex3:words:3:pos":"verb","grammar:8110:ex3:points:0":"❗〜を謝る: to apologize for…; 間違えたこと = the thing you got wrong.","grammar:8110:ex3:points:1":"謝る: to apologize.","grammar:8110:ex4:trans":"Apologizing takes courage.","grammar:8110:ex4:structure":"謝るのは勇気がいる","grammar:8110:ex4:words:0:zh":"apology","grammar:8110:ex4:words:0:note":"あやまる","grammar:8110:ex4:words:0:pos":"verb","grammar:8110:ex4:words:1:zh":"(nominalizer)","grammar:8110:ex4:words:1:pos":"particle","grammar:8110:ex4:words:2:zh":"(topic)","grammar:8110:ex4:words:2:pos":"particle","grammar:8110:ex4:words:3:zh":"courage","grammar:8110:ex4:words:3:note":"ゆうき","grammar:8110:ex4:words:3:pos":"noun","grammar:8110:ex4:words:4:zh":"(nominative)","grammar:8110:ex4:words:4:pos":"particle","grammar:8110:ex4:words:5:zh":"require; need","grammar:8110:ex4:words:5:pos":"verb","grammar:8110:ex4:points:0":"❗〜がいる: to need… (いる = to need); 謝るのは勇気がいる = apologizing takes courage.","grammar:8110:ex4:points:1":"勇気がいる: to take courage.","grammar:8110:ex5:trans":"After I apologized to her, I felt relieved.","grammar:8110:ex5:structure":"〜に謝った後、すっきりした","grammar:8110:ex5:words:0:zh":"she","grammar:8110:ex5:words:0:note":"かのじょ","grammar:8110:ex5:words:0:pos":"pronoun","grammar:8110:ex5:words:1:zh":"(object)","grammar:8110:ex5:words:1:pos":"particle","grammar:8110:ex5:words:2:zh":"apologized","grammar:8110:ex5:words:2:note":"あやまった","grammar:8110:ex5:words:2:pos":"verb","grammar:8110:ex5:words:3:zh":"later, afterwards","grammar:8110:ex5:words:3:note":"あと","grammar:8110:ex5:words:3:pos":"noun","grammar:8110:ex5:words:4:zh":"felt refreshed","grammar:8110:ex5:words:4:note":"すっきりした","grammar:8110:ex5:words:4:pos":"verb","grammar:8110:ex5:points:0":"❗〜た後: after…; すっきりする = to feel refreshed, to feel relieved.","grammar:8110:ex5:points:1":"謝った後: after apologizing."},"8111":{"example:8111:exzh":"His wish came true.","example:8111:exzh2":"I believe my wish will come true.","example:8111:exzh3":"At New Year, people write down their wishes.","example:8111:exzh4":"Let's cherish our wishes.","example:8111:exzh5":"Her wish is to be happy."},"8112":{"example:8112:exzh":"He is making advances toward her.","example:8112:exzh2":"It takes courage to court someone.","example:8112:exzh3":"I'd be happy if someone made advances toward me.","example:8112:exzh4":"She isn't comfortable with people making advances toward her.","example:8112:exzh5":"Please stop making advances."},"8113":{"example:8113:exzh":"This explanation is clear.","example:8113:exzh2":"Her opinion was clear.","example:8113:exzh3":"Clear information is needed.","example:8113:exzh4":"If it isn't clear, it causes confusion.","example:8113:exzh5":"Please speak in clear language."},"8114":{"example:8114:exzh":"They often argue.","example:8114:exzh2":"Sometimes you argue with friends, too.","example:8114:exzh3":"I want to avoid arguing.","example:8114:exzh4":"Arguing with family is painful.","example:8114:exzh5":"I'm tired from arguing."},"8115":{"example:8115:exzh":"The pharaoh was the king of ancient Egypt.","example:8115:exzh2":"The pharaoh's tomb was discovered.","example:8115:exzh3":"The age of the pharaohs is fascinating.","example:8115:exzh4":"The pharaoh was worshipped like a god.","example:8115:exzh5":"The pharaohs and the pyramids are famous."},"8116":{"example:8116:exzh":"Holy water is used in sacred places.","example:8116:exzh2":"Holy water was handed out during the festival.","example:8116:exzh3":"He went to the temple seeking holy water.","example:8116:exzh4":"It's said that using holy water drives away bad luck.","example:8116:exzh5":"She keeps holy water as a source of emotional support."},"8117":{"example:8117:exzh":"It's not good to act superior.","example:8117:exzh2":"He always tries to act superior.","example:8117:exzh3":"On social media, people compete to one-up each other.","example:8117:exzh4":"I like talking with friends about showing off.","example:8117:exzh5":"It turned into a contest of one-upmanship."},"8118":{"example:8118:exzh":"Sometimes correction is necessary.","example:8118:exzh2":"He is going to an orthodontic clinic.","example:8118:exzh3":"Getting orthodontic treatment improves your appearance.","example:8118:exzh4":"I have to get my eyesight corrected.","example:8118:exzh5":"Corrective treatment takes time."},"8119":{"example:8119:exzh":"I was amazed by his extraordinary talent.","example:8119:exzh2":"It was an unusual situation, so everyone was confused.","example:8119:exzh3":"This product has a unique design.","example:8119:exzh4":"She is valued for her unique perspective.","example:8119:exzh5":"Unique experiences make life richer."},"8121":{"example:8121:exzh":"The old wallpaper is starting to peel off.","example:8121:exzh2":"The children are peeling off stickers.","example:8121:exzh3":"Tearing meat off is difficult work.","example:8121:exzh4":"You need to peel off the juice label.","example:8121:exzh5":"She isn't good at peeling off bandages."},"8122":{"example:8122:exzh":"I put pickles in the sandwich.","example:8122:exzh2":"He loves pickles.","example:8122:exzh3":"Pickles are popular as a side dish.","example:8122:exzh4":"I topped the salad with pickles.","example:8122:exzh5":"Be careful not to eat too many pickles."},"8123":{"example:8123:exzh":"They exchanged opinions as people in the same trade.","example:8123:exzh2":"I took part in a gathering of people in the same industry.","example:8123:exzh3":"I have many friends in the same industry.","example:8123:exzh4":"Sometimes I get support from others in the same field.","example:8123:exzh5":"He is respected by others in the same industry."},"8124":{"example:8124:exzh":"This school has a high standard.","example:8124:exzh2":"I want to raise his level.","example:8124:exzh3":"It's important to maintain the standard.","example:8124:exzh4":"People are calling for higher living standards.","example:8124:exzh5":"His academic level is valued."},"8125":{"example:8125:exzh":"The stock price crashed.","example:8125:exzh2":"A market crash can't be predicted.","example:8125:exzh3":"He's worried about the crash.","example:8125:exzh4":"This crash affected many people.","example:8125:exzh5":"An economic crash is a serious problem."},"8126":{"example:8126:exzh":"Good news arrived.","example:8126:exzh2":"That's good news, isn't it.","example:8126:exzh3":"I'm waiting for good news from her.","example:8126:exzh4":"If there's good news, tell me right away.","example:8126:exzh5":"We all celebrated today's good news together."},"8127":{"example:8127:exzh":"He's an excellent carpenter.","example:8127:exzh2":"Carpentry is hard work.","example:8127:exzh3":"My house is something a carpenter did as a DIY project.","example:8127:exzh4":"I want to learn carpentry skills.","example:8127:exzh5":"That carpenter is a master.","grammar:8127:ex:trans":"He is an excellent carpenter.","grammar:8127:ex:structure":"彼は＋優れた大工です","grammar:8127:ex:explain":"This is a judgment sentence, AはBです: 「彼は」 marks the topic, and the predicate is the noun phrase 「優れた大工」 plus 「です」. The key part is 「優れた大工」: the ta-form of the verb 「優れる」 modifies the noun 「大工」, meaning “an excellent carpenter.” Although 「優れた」 has the shape of a past-tense verb, by convention it is understood as “excellent” — a fixed attributive usage. The whole sentence means he is an excellent carpenter.","grammar:8127:ex:words:0:zh":"he","grammar:8127:ex:words:0:note":"かれ","grammar:8127:ex:words:0:pos":"pronoun","grammar:8127:ex:words:1:zh":"(topic)","grammar:8127:ex:words:1:pos":"particle","grammar:8127:ex:words:2:zh":"excellent","grammar:8127:ex:words:2:note":"すぐれた","grammar:8127:ex:words:2:pos":"verb (attributive form)","grammar:8127:ex:words:3:zh":"carpenter","grammar:8127:ex:words:3:note":"だいく","grammar:8127:ex:words:3:pos":"noun","grammar:8127:ex:words:4:zh":"(assertion · polite)","grammar:8127:ex:words:4:pos":"auxiliary verb","grammar:8127:ex:points:0":"「優れた＋noun」 = excellent ~ (優れた大工), attributive modification","grammar:8127:ex:points:1":"AはBです: A is B (彼は…大工)","grammar:8127:ex2:trans":"A carpenter's work is hard.","grammar:8127:ex2:structure":"大工の仕事は＋大変です","grammar:8127:ex2:words:0:zh":"carpenter","grammar:8127:ex2:words:0:note":"だいく","grammar:8127:ex2:words:0:pos":"noun","grammar:8127:ex2:words:1:zh":"'s","grammar:8127:ex2:words:1:pos":"particle","grammar:8127:ex2:words:2:zh":"work","grammar:8127:ex2:words:2:note":"しごと","grammar:8127:ex2:words:2:pos":"noun","grammar:8127:ex2:words:3:zh":"(topic)","grammar:8127:ex2:words:3:pos":"particle","grammar:8127:ex2:words:4:zh":"tough","grammar:8127:ex2:words:4:note":"たいへん","grammar:8127:ex2:words:4:pos":"na-adjective","grammar:8127:ex2:words:5:zh":"(assertion · polite)","grammar:8127:ex2:words:5:pos":"auxiliary verb","grammar:8127:ex2:points:0":"「大変だ」: na-adjective in polite form (tough)","grammar:8127:ex2:points:1":"の linking nouns: 大工の仕事 (a carpenter's work)","grammar:8127:ex3:trans":"My house is something a carpenter built by hand.","grammar:8127:ex3:structure":"家は＋大工がDIYしたものです","grammar:8127:ex3:words:0:zh":"I","grammar:8127:ex3:words:0:note":"わたし","grammar:8127:ex3:words:0:pos":"pronoun","grammar:8127:ex3:words:1:zh":"'s","grammar:8127:ex3:words:1:pos":"particle","grammar:8127:ex3:words:2:zh":"house, home","grammar:8127:ex3:words:2:note":"いえ","grammar:8127:ex3:words:2:pos":"noun","grammar:8127:ex3:words:3:zh":"(topic)","grammar:8127:ex3:words:3:pos":"particle","grammar:8127:ex3:words:4:zh":"carpenter","grammar:8127:ex3:words:4:note":"だいく","grammar:8127:ex3:words:4:pos":"noun","grammar:8127:ex3:words:5:zh":"(subject marker inside a noun-modifying clause)","grammar:8127:ex3:words:5:pos":"particle","grammar:8127:ex3:words:6:zh":"made by hand (ta-form, attributive)","grammar:8127:ex3:words:6:note":"でぃーあいわいした","grammar:8127:ex3:words:6:pos":"verb","grammar:8127:ex3:words:7:zh":"things","grammar:8127:ex3:words:7:pos":"formal noun","grammar:8127:ex3:words:8:zh":"(assertion · polite)","grammar:8127:ex3:words:8:pos":"auxiliary verb","grammar:8127:ex3:points:0":"Contains an attributive clause: 大工がDIYした＋もの (something a carpenter made by hand)","grammar:8127:ex3:points:1":"AはBものです: A is the thing that B (emphasizes where it came from)","grammar:8127:ex4:trans":"I want to learn carpentry skills.","grammar:8127:ex4:structure":"大工の技術を＋学びたいです","grammar:8127:ex4:words:0:zh":"carpenter","grammar:8127:ex4:words:0:note":"だいく","grammar:8127:ex4:words:0:pos":"noun","grammar:8127:ex4:words:1:zh":"'s","grammar:8127:ex4:words:1:pos":"particle","grammar:8127:ex4:words:2:zh":"technology","grammar:8127:ex4:words:2:note":"ぎじゅつ","grammar:8127:ex4:words:2:pos":"noun","grammar:8127:ex4:words:3:zh":"(object marker)","grammar:8127:ex4:words:3:pos":"particle","grammar:8127:ex4:words:4:zh":"want to learn (desire)","grammar:8127:ex4:words:4:note":"まなびたい","grammar:8127:ex4:words:4:pos":"verb","grammar:8127:ex4:words:5:zh":"(polite)","grammar:8127:ex4:words:5:pos":"auxiliary verb","grammar:8127:ex4:points:0":"〜たい: to want to 〜 (学びたい = want to learn); desire","grammar:8127:ex4:points:1":"の linking nouns: 大工の技術 (a carpenter's skills)","grammar:8127:ex5:trans":"That carpenter is a master.","grammar:8127:ex5:structure":"大工は＋名人です","grammar:8127:ex5:words:0:zh":"that","grammar:8127:ex5:words:0:pos":"pre-noun adjectival","grammar:8127:ex5:words:1:zh":"carpenter","grammar:8127:ex5:words:1:note":"だいく","grammar:8127:ex5:words:1:pos":"noun","grammar:8127:ex5:words:2:zh":"(topic)","grammar:8127:ex5:words:2:pos":"particle","grammar:8127:ex5:words:3:zh":"master, expert","grammar:8127:ex5:words:3:note":"めいじん","grammar:8127:ex5:words:3:pos":"noun","grammar:8127:ex5:words:4:zh":"(assertion · polite)","grammar:8127:ex5:words:4:pos":"auxiliary verb","grammar:8127:ex5:points:0":"AはBです: A is B (大工は…名人)","grammar:8127:ex5:points:1":"Pre-noun adjectival 「その」 + noun (that carpenter)"},"8128":{"example:8128:exzh":"A scratch heals quickly.","example:8128:exzh2":"He fell and got a scrape.","example:8128:exzh3":"Scratches need disinfecting.","example:8128:exzh4":"A small scratch is nothing to worry about.","example:8128:exzh5":"A scratch doesn't hurt."},"8129":{"example:8129:exzh":"Breaking news was reported.","example:8129:exzh2":"His breaking news was broadcast on the channel.","example:8129:exzh3":"I was surprised to hear the breaking news.","example:8129:exzh4":"People are waiting for new breaking news.","example:8129:exzh5":"I'm waiting for breaking news to come in."},"8131":{"example:8131:exzh":"Please be careful when using a burner.","example:8131:exzh2":"Do you need a burner?","example:8131:exzh3":"I cook with a burner.","example:8131:exzh4":"The burner flame is too strong.","example:8131:exzh5":"I bought a new burner."},"8132":{"example:8132:exzh":"The ball bounced with a pop.","example:8132:exzh2":"Please give it a light tap.","example:8132:exzh3":"There was a popping sound.","example:8132:exzh4":"He clapped his hands with a pop.","example:8132:exzh5":"The balloon popped."},"8133":{"example:8133:exzh":"I put out the fire with a fire extinguisher.","example:8133:exzh2":"Firefighting efforts are important.","example:8133:exzh3":"The fire was put out in time.","example:8133:exzh4":"I've had firefighting training.","example:8133:exzh5":"Let's check the firefighting equipment."},"8135":{"example:8135:exzh":"The clock ticks.","example:8135:exzh2":"I heard a tick.","example:8135:exzh3":"The ticking is soothing.","example:8135:exzh4":"He walks making a ticking sound.","example:8135:exzh5":"The game's sound effect is a tick."},"8136":{"example:8136:exzh":"Let's go to a disco.","example:8136:exzh2":"He dances at the disco.","example:8136:exzh3":"Disco music is fun.","example:8136:exzh4":"I went to a disco with a friend.","example:8136:exzh5":"I like the atmosphere of discos."},"8137":{"example:8137:exzh":"Let's share the work.","example:8137:exzh2":"I understand the importance of sharing tasks.","example:8137:exzh3":"We divide the work among the team.","example:8137:exzh4":"Let's share the burden.","example:8137:exzh5":"They shared responsibility."},"8138":{"example:8138:exzh":"He has a great physique.","example:8138:exzh2":"I also exercise to maintain my figure.","example:8138:exzh3":"This physique is due to genetics.","example:8138:exzh4":"Let's aim for a healthy physique.","example:8138:exzh5":"If you're worried about your figure, pay attention to your diet."},"8139":{"example:8139:exzh":"He pushed the ball out.","example:8139:exzh2":"It's difficult to push that idea forward.","example:8139:exzh3":"We need to push the new product onto the market.","example:8139:exzh4":"Let's use pushing force to move it.","example:8139:exzh5":"The idea that was pushed forward is feasible."},"8140":{"example:8140:exzh":"This shipping route is especially crowded.","example:8140:exzh2":"We need to change the shipping route.","example:8140:exzh3":"It's important to choose a safe shipping route.","example:8140:exzh4":"A new shipping route has been opened.","example:8140:exzh5":"That shipping route was shortened."},"8141":{"example:8141:exzh":"I'll take advantage of spring break to go on a trip.","example:8141:exzh2":"The children are looking forward to spring break.","example:8141:exzh3":"Don't forget your spring break homework.","example:8141:exzh4":"I'll spend spring break with my family.","example:8141:exzh5":"There are lots of events during spring break.","grammar:8141:ex:trans":"I'll use spring break to go on a trip.","grammar:8141:ex:structure":"春休みを＋〔利用して〕、旅行に＋行きます. 「〜を利用して」 = to make use of …","grammar:8141:ex:explain":"The pattern 「〜を利用して」 means “making use of … (to do something)”. The thing being used, 「春休み」 (spring break), takes 「を」, and 「利用して」 is the te-form expressing the means or the occasion. It's followed by 「旅行に行きます」, where 「に」 marks the purpose (going on a trip). The whole sentence means “I'll use spring break to go on a trip.” The 「〜を利用して＋action」 pattern is commonly used to say that you take advantage of some opportunity or resource to do something.","grammar:8141:ex:words:0:zh":"spring break","grammar:8141:ex:words:0:note":"はるやすみ","grammar:8141:ex:words:0:pos":"noun","grammar:8141:ex:words:1:zh":"(object marker)","grammar:8141:ex:words:1:pos":"particle","grammar:8141:ex:words:2:zh":"using (and)","grammar:8141:ex:words:2:note":"りようして; te-form","grammar:8141:ex:words:2:pos":"verb","grammar:8141:ex:words:3:zh":"travel / trip","grammar:8141:ex:words:3:note":"りょこう","grammar:8141:ex:words:3:pos":"noun","grammar:8141:ex:words:4:zh":"(purpose)","grammar:8141:ex:words:4:pos":"particle","grammar:8141:ex:words:5:zh":"go","grammar:8141:ex:words:5:note":"いきます","grammar:8141:ex:words:5:pos":"verb","grammar:8141:ex:points:0":"〜を利用して: making use of …","grammar:8141:ex:points:1":"春休み: spring break","grammar:8141:ex2:trans":"The kids are looking forward to spring break.","grammar:8141:ex2:structure":"〜は＋春休みを＋楽しみにしています. 「〜を楽しみにする」 = to look forward to …","grammar:8141:ex2:words:0:zh":"the kids","grammar:8141:ex2:words:0:note":"こどもたち","grammar:8141:ex2:words:0:pos":"noun","grammar:8141:ex2:words:1:zh":"(topic marker)","grammar:8141:ex2:words:1:pos":"particle","grammar:8141:ex2:words:2:zh":"spring break","grammar:8141:ex2:words:2:note":"はるやすみ","grammar:8141:ex2:words:2:pos":"noun","grammar:8141:ex2:words:3:zh":"(object marker)","grammar:8141:ex2:words:3:pos":"particle","grammar:8141:ex2:words:4:zh":"look forward to","grammar:8141:ex2:words:4:note":"〜ている expresses a state","grammar:8141:ex2:words:4:pos":"verb","grammar:8141:ex2:points:0":"〜を楽しみにする: to look forward to…","grammar:8141:ex2:points:1":"春休み: spring break","grammar:8141:ex3:trans":"Don't forget the spring break homework.","grammar:8141:ex3:structure":"〔春休みの宿題〕＋を＋忘れないでください. 「〜ないでください」 = please don't …","grammar:8141:ex3:words:0:zh":"spring break","grammar:8141:ex3:words:0:note":"はるやすみ","grammar:8141:ex3:words:0:pos":"noun","grammar:8141:ex3:words:1:zh":"'s","grammar:8141:ex3:words:1:pos":"particle","grammar:8141:ex3:words:2:zh":"homework","grammar:8141:ex3:words:2:note":"しゅくだい","grammar:8141:ex3:words:2:pos":"noun","grammar:8141:ex3:words:3:zh":"(object marker)","grammar:8141:ex3:words:3:pos":"particle","grammar:8141:ex3:words:4:zh":"don't forget","grammar:8141:ex3:words:4:note":"〜ないで","grammar:8141:ex3:words:4:pos":"verb","grammar:8141:ex3:words:5:zh":"please","grammar:8141:ex3:words:5:note":"〜ないでください","grammar:8141:ex3:words:5:pos":"verb","grammar:8141:ex3:points:0":"〜ないでください: please don't…","grammar:8141:ex3:points:1":"春休みの宿題: spring break homework","grammar:8141:ex4:trans":"I'll spend spring break with my family.","grammar:8141:ex4:structure":"春休みは、家族と＋過ごします. 「〜と過ごす」 = to spend time with …","grammar:8141:ex4:words:0:zh":"spring break","grammar:8141:ex4:words:0:note":"はるやすみ","grammar:8141:ex4:words:0:pos":"noun","grammar:8141:ex4:words:1:zh":"(topic marker)","grammar:8141:ex4:words:1:pos":"particle","grammar:8141:ex4:words:2:zh":"family","grammar:8141:ex4:words:2:note":"かぞく","grammar:8141:ex4:words:2:pos":"noun","grammar:8141:ex4:words:3:zh":"with","grammar:8141:ex4:words:3:pos":"particle","grammar:8141:ex4:words:4:zh":"spend","grammar:8141:ex4:words:4:note":"すごします","grammar:8141:ex4:words:4:pos":"verb","grammar:8141:ex4:points:0":"〜と過ごす: to spend (time) with …","grammar:8141:ex4:points:1":"春休み: spring break","grammar:8141:ex5:trans":"There are lots of events during spring break.","grammar:8141:ex5:structure":"春休み＋には＋〔たくさんのイベント〕＋が＋あります. 「〜には」 = in/at … (emphasizing the time).","grammar:8141:ex5:words:0:zh":"spring break","grammar:8141:ex5:words:0:note":"はるやすみ","grammar:8141:ex5:words:0:pos":"noun","grammar:8141:ex5:words:1:zh":"(time + emphasis)","grammar:8141:ex5:words:1:pos":"particle","grammar:8141:ex5:words:2:zh":"a lot","grammar:8141:ex5:words:2:pos":"adverb","grammar:8141:ex5:words:3:zh":"'s","grammar:8141:ex5:words:3:pos":"particle","grammar:8141:ex5:words:4:zh":"event","grammar:8141:ex5:words:4:note":"loanword","grammar:8141:ex5:words:4:pos":"noun","grammar:8141:ex5:words:5:zh":"(nominative)","grammar:8141:ex5:words:5:pos":"particle","grammar:8141:ex5:words:6:zh":"there is / are","grammar:8141:ex5:words:6:note":"exists / there is","grammar:8141:ex5:words:6:pos":"verb","grammar:8141:ex5:points:0":"〜には: in/at … (emphasizing the time; 春休みには = during spring break)","grammar:8141:ex5:points:1":"たくさんのイベント: lots of events"},"8142":{"example:8142:exzh":"He announced his own name.","example:8142:exzh2":"Introducing yourself is important etiquette.","example:8142:exzh3":"Take a deep breath before introducing yourself.","example:8142:exzh4":"She introduced herself clearly.","example:8142:exzh5":"It's best to introduce yourself briefly."},"8144":{"example:8144:exzh":"I'm learning martial arts for self-defense.","example:8144:exzh2":"Self-defense is always important.","example:8144:exzh3":"He has self-defense skills.","example:8144:exzh4":"I took a self-defense class.","example:8144:exzh5":"Everyone needs self-defense."},"8145":{"example:8145:exzh":"She's good at creative work.","example:8145:exzh2":"This book is my creation.","example:8145:exzh3":"I like taking part in creative activities.","example:8145:exzh4":"Creation takes time.","example:8145:exzh5":"His work is moving."},"8146":{"example:8146:exzh":"Please read the terms of service carefully.","example:8146:exzh2":"You must agree to the terms.","example:8146:exzh3":"These terms may change.","example:8146:exzh4":"Violating the terms will be punished.","example:8146:exzh5":"New terms have been announced."},"8147":{"example:8147:exzh":"He likes to compete.","example:8147:exzh2":"I compete with my friends.","example:8147:exzh3":"I won first place at the competition.","example:8147:exzh4":"It's an industry with tough competition.","example:8147:exzh5":"We compete with each other."},"8148":{"example:8148:exzh":"He gave his thanks courteously.","example:8148:exzh2":"It's important to use courteous language.","example:8148:exzh3":"Please handle it with care.","example:8148:exzh4":"She is always courteous.","example:8148:exzh5":"A sense of courtesy came through."},"8149":{"example:8149:exzh":"She is a psychic.","example:8149:exzh2":"There is healing that uses psychic power.","example:8149:exzh3":"I like learning about psychic power.","example:8149:exzh4":"Whether or not you believe in psychic power is up to each person.","example:8149:exzh5":"He is said to have psychic power."},"8150":{"example:8150:exzh":"Pineapple is sweet and delicious.","example:8150:exzh2":"I like desserts made with pineapple.","example:8150:exzh3":"I want to drink cold pineapple juice.","example:8150:exzh4":"I sliced the pineapple.","example:8150:exzh5":"I ate pineapple for breakfast.","grammar:8150:ex:trans":"Pineapple is sweet and delicious.","grammar:8150:ex:structure":"パイナップルは、〔甘くて＋おいしい〕です. 「甘くて」 uses the te-form to link two adjectives.","grammar:8150:ex:explain":"The key point is linking i-adjectives with the te-form: drop the 「い」 from 「甘い」 and add 「くて」 to get 「甘くて」, which links to the following 「おいしい」, expressing that it is both sweet and delicious. 「パイナップルは」 sets the topic, and 「です」 at the end makes the adjective polite. This 「〜くて〜」 pattern is the basic way to list several qualities at once.","grammar:8150:ex:words:0:zh":"pineapple","grammar:8150:ex:words:0:note":"loanword: pineapple","grammar:8150:ex:words:0:pos":"noun","grammar:8150:ex:words:1:zh":"(topic marker)","grammar:8150:ex:words:1:pos":"particle","grammar:8150:ex:words:2:zh":"sweet (and)","grammar:8150:ex:words:2:note":"あまくて; i-adjective te-form","grammar:8150:ex:words:2:pos":"adjective","grammar:8150:ex:words:3:zh":"tasty","grammar:8150:ex:words:3:pos":"adjective","grammar:8150:ex:words:4:zh":"(polite form)","grammar:8150:ex:words:4:pos":"copula","grammar:8150:ex:points:0":"i-adjective te-form: 甘い→甘くて (sweet and …)","grammar:8150:ex:points:1":"パイナップル: pineapple","grammar:8150:ex2:trans":"I like desserts made with pineapple.","grammar:8150:ex2:structure":"〔パイナップルを使った〕＋デザート＋が＋好きです. 「パイナップルを使った」 modifies 「デザート」.","grammar:8150:ex2:words:0:zh":"pineapple","grammar:8150:ex2:words:0:note":"loanword","grammar:8150:ex2:words:0:pos":"noun","grammar:8150:ex2:words:1:zh":"(object marker)","grammar:8150:ex2:words:1:pos":"particle","grammar:8150:ex2:words:2:zh":"using","grammar:8150:ex2:words:2:note":"ta-form modification","grammar:8150:ex2:words:2:pos":"verb","grammar:8150:ex2:words:3:zh":"dessert","grammar:8150:ex2:words:3:note":"loanword","grammar:8150:ex2:words:3:pos":"noun","grammar:8150:ex2:words:4:zh":"(object marker)","grammar:8150:ex2:words:4:pos":"particle","grammar:8150:ex2:words:5:zh":"to like","grammar:8150:ex2:words:5:note":"すき","grammar:8150:ex2:words:5:pos":"na-adjective","grammar:8150:ex2:words:6:zh":"(polite form)","grammar:8150:ex2:words:6:pos":"copula","grammar:8150:ex2:points:0":"verb ta-form modifying a noun: 使ったデザート (a dessert made with …)","grammar:8150:ex2:points:1":"パイナップルを使う: to use pineapple","grammar:8150:ex3:trans":"I want to drink cold pineapple juice.","grammar:8150:ex3:structure":"〔冷たいパイナップルジュース〕＋が＋飲みたいです. 「〜が飲みたい」 = to want to drink …","grammar:8150:ex3:words:0:zh":"cold","grammar:8150:ex3:words:0:note":"つめたい","grammar:8150:ex3:words:0:pos":"adjective","grammar:8150:ex3:words:1:zh":"pineapple juice","grammar:8150:ex3:words:1:note":"loanword","grammar:8150:ex3:words:1:pos":"noun","grammar:8150:ex3:words:2:zh":"(object marker)","grammar:8150:ex3:words:2:pos":"particle","grammar:8150:ex3:words:3:zh":"want to drink","grammar:8150:ex3:words:3:note":"〜たい expresses desire","grammar:8150:ex3:words:3:pos":"verb","grammar:8150:ex3:words:4:zh":"(polite form)","grammar:8150:ex3:words:4:pos":"copula","grammar:8150:ex3:points:0":"〜が飲みたい: want to drink …","grammar:8150:ex3:points:1":"冷たいパイナップルジュース: cold pineapple juice","grammar:8150:ex4:trans":"I sliced the pineapple.","grammar:8150:ex4:structure":"noun＋を＋スライスしました. 「スライスする」 = to slice.","grammar:8150:ex4:words:0:zh":"pineapple","grammar:8150:ex4:words:0:note":"loanword","grammar:8150:ex4:words:0:pos":"noun","grammar:8150:ex4:words:1:zh":"(object marker)","grammar:8150:ex4:words:1:pos":"particle","grammar:8150:ex4:words:2:zh":"sliced","grammar:8150:ex4:words:2:note":"loanword verb: slice","grammar:8150:ex4:words:2:pos":"verb","grammar:8150:ex4:points:0":"スライスする: to slice","grammar:8150:ex4:points:1":"パイナップル: pineapple","grammar:8150:ex5:trans":"I ate pineapple for breakfast.","grammar:8150:ex5:structure":"朝ごはんに、パイナップルを＋食べました. 「〜に」 marks a point in time.","grammar:8150:ex5:words:0:zh":"breakfast","grammar:8150:ex5:words:0:note":"あさごはん","grammar:8150:ex5:words:0:pos":"noun","grammar:8150:ex5:words:1:zh":"(point in time)","grammar:8150:ex5:words:1:pos":"particle","grammar:8150:ex5:words:2:zh":"pineapple","grammar:8150:ex5:words:2:note":"loanword","grammar:8150:ex5:words:2:pos":"noun","grammar:8150:ex5:words:3:zh":"(object marker)","grammar:8150:ex5:words:3:pos":"particle","grammar:8150:ex5:words:4:zh":"ate","grammar:8150:ex5:words:4:note":"たべました","grammar:8150:ex5:words:4:pos":"verb","grammar:8150:ex5:points:0":"朝ごはんに: at breakfast","grammar:8150:ex5:points:1":"パイナップル: pineapple"},"8151":{"example:8151:exzh":"I want to eat authentic sushi.","example:8151:exzh2":"I brewed authentic coffee.","example:8151:exzh3":"I started authentic training.","example:8151:exzh4":"You can enjoy authentic cuisine at this restaurant.","example:8151:exzh5":"I tried authentic sake."},"8152":{"example:8152:exzh":"This employee has essential skills.","example:8152:exzh2":"Please submit the required documents.","example:8152:exzh3":"I'm taking the required courses.","example:8152:exzh4":"This job requires an essential qualification.","example:8152:exzh5":"Please complete the required procedures."},"8153":{"example:8153:exzh":"He attacked in the soccer match.","example:8153:exzh2":"Launch an attack on the enemy.","example:8153:exzh3":"This technique is useful for attacking.","example:8153:exzh4":"We need to strengthen the attack.","example:8153:exzh5":"Make an effective attack."},"8154":{"example:8154:exzh":"He showed respect to his elders.","example:8154:exzh2":"I have an older brother.","example:8154:exzh3":"It's important to listen to the opinions of your elders.","example:8154:exzh4":"I go out to have fun with an older friend.","example:8154:exzh5":"An older teacher is teaching."},"8155":{"example:8155:exzh":"He has asthma symptoms.","example:8155:exzh2":"Many people suffer from asthma.","example:8155:exzh3":"If your asthma gets worse, you should go to the hospital.","example:8155:exzh4":"My friend can't exercise because of asthma.","example:8155:exzh5":"I'm looking for a treatment for asthma."},"8156":{"example:8156:exzh":"That emperor made the country prosper.","example:8156:exzh2":"The emperor's power was absolute.","example:8156:exzh3":"He dreams of becoming an emperor.","example:8156:exzh4":"I study the history of the imperial system.","example:8156:exzh5":"That emperor won many wars."},"8157":{"example:8157:exzh":"She has a mysterious air.","example:8157:exzh2":"I want to go to a mysterious place.","example:8157:exzh3":"That movie has a lot of mysterious elements.","example:8157:exzh4":"I want to have a mysterious experience.","example:8157:exzh5":"I like mysterious stories."},"8158":{"example:8158:exzh":"How's today going?","example:8158:exzh2":"Is she doing well? How are things?","example:8158:exzh3":"How's your studying going?","example:8158:exzh4":"How do we solve the problem?","example:8158:exzh5":"How's your job?","grammar:8158:ex:trans":"How's today going?","grammar:8158:ex:structure":"〜はどうですか","grammar:8158:ex:explain":"The key is the question adverb 「どう」, meaning how, used to ask about a state, a situation, or the other person's opinion. 「どうですか」 means how is it. 「今日は」 uses 「は」 to present today as the topic. The final 「か」 is the question particle. This is a very common pattern for greetings and asking how someone feels, as in 「調子はどうですか」 (how are things going?).","grammar:8158:ex:words:0:zh":"today","grammar:8158:ex:words:0:note":"きょう","grammar:8158:ex:words:0:pos":"noun","grammar:8158:ex:words:1:zh":"(topic)","grammar:8158:ex:words:1:pos":"particle","grammar:8158:ex:words:2:zh":"how","grammar:8158:ex:words:2:pos":"adverb","grammar:8158:ex:words:3:zh":"(polite form)","grammar:8158:ex:words:3:pos":"copula","grammar:8158:ex:words:4:zh":"(question)","grammar:8158:ex:words:4:pos":"particle","grammar:8158:ex:points:0":"❗どう：how it is, how things are (asking about a state).","grammar:8158:ex:points:1":"どうですか：how is it, how about it.","grammar:8158:ex2:trans":"Is she doing well? How about it?","grammar:8158:ex2:structure":"〜ですか？どう？","grammar:8158:ex2:words:0:zh":"she","grammar:8158:ex2:words:0:note":"かのじょ","grammar:8158:ex2:words:0:pos":"pronoun","grammar:8158:ex2:words:1:zh":"(topic)","grammar:8158:ex2:words:1:pos":"particle","grammar:8158:ex2:words:2:zh":"health","grammar:8158:ex2:words:2:note":"げんき","grammar:8158:ex2:words:2:pos":"na-adjective","grammar:8158:ex2:words:3:zh":"(polite form)","grammar:8158:ex2:words:3:pos":"copula","grammar:8158:ex2:words:4:zh":"(question)","grammar:8158:ex2:words:4:pos":"particle","grammar:8158:ex2:words:5:zh":"(casual speech) how about it","grammar:8158:ex2:words:5:pos":"adverb","grammar:8158:ex2:points:0":"❗「どお」 is the casual spelling of 「どう」.","grammar:8158:ex2:points:1":"元気ですか：are you well?","grammar:8158:ex3:trans":"How's the studying going?","grammar:8158:ex3:structure":"〜はどうですか","grammar:8158:ex3:words:0:zh":"study","grammar:8158:ex3:words:0:note":"べんきょう","grammar:8158:ex3:words:0:pos":"noun","grammar:8158:ex3:words:1:zh":"(topic)","grammar:8158:ex3:words:1:pos":"particle","grammar:8158:ex3:words:2:zh":"how","grammar:8158:ex3:words:2:pos":"adverb","grammar:8158:ex3:words:3:zh":"(polite form)","grammar:8158:ex3:words:3:pos":"copula","grammar:8158:ex3:words:4:zh":"(question)","grammar:8158:ex3:words:4:pos":"particle","grammar:8158:ex3:points:0":"勉強はどう：how the studies are going.","grammar:8158:ex3:points:1":"どうですか：how is it.","grammar:8158:ex4:trans":"How should the problem be solved?","grammar:8158:ex4:structure":"〜はどう〜する？","grammar:8158:ex4:words:0:zh":"problem","grammar:8158:ex4:words:0:note":"もんだい","grammar:8158:ex4:words:0:pos":"noun","grammar:8158:ex4:words:1:zh":"(topic)","grammar:8158:ex4:words:1:pos":"particle","grammar:8158:ex4:words:2:zh":"how","grammar:8158:ex4:words:2:pos":"adverb","grammar:8158:ex4:words:3:zh":"solve","grammar:8158:ex4:words:3:note":"かいけつする","grammar:8158:ex4:words:3:pos":"verb","grammar:8158:ex4:points:0":"❗どう＋verb：how (to do) … (the method).","grammar:8158:ex4:points:1":"どう解決する：how to solve it.","grammar:8158:ex5:trans":"How's your job?","grammar:8158:ex5:structure":"〜はどう？","grammar:8158:ex5:words:0:zh":"you","grammar:8158:ex5:words:0:pos":"pronoun","grammar:8158:ex5:words:1:zh":"'s","grammar:8158:ex5:words:1:pos":"particle","grammar:8158:ex5:words:2:zh":"work","grammar:8158:ex5:words:2:note":"しごと","grammar:8158:ex5:words:2:pos":"noun","grammar:8158:ex5:words:3:zh":"(topic)","grammar:8158:ex5:words:3:pos":"particle","grammar:8158:ex5:words:4:zh":"how","grammar:8158:ex5:words:4:pos":"adverb","grammar:8158:ex5:points:0":"どう？：how about it (casual speech, です omitted).","grammar:8158:ex5:points:1":"あなたの仕事：your job.","exam:8158:zh":"I wanted to know whether the new school is fun, so I asked my younger brother, “How's the new school?”","exam:8158:why":"「どう」 asks about a situation or an impression, which fits the goal of finding out whether the school is fun. 「どこ」 asks about a place."},"8160":{"example:8160:exzh":"Sometimes you need a break.","example:8160:exzh2":"I take a breather after work.","example:8160:exzh3":"A walk is a good way to take a break.","example:8160:exzh4":"Without a break, you get tired.","example:8160:exzh5":"Games are a way for me to unwind."},"8161":{"example:8161:exzh":"Evil has spread.","example:8161:exzh2":"We have to eliminate evil.","example:8161:exzh3":"He admitted his mistake.","example:8161:exzh4":"I want to think about how to make evil good.","example:8161:exzh5":"Nothing good comes from continuing to do evil."},"8162":{"example:8162:exzh":"It looks upside down in the mirror.","example:8162:exzh2":"An upside-down picture is interesting.","example:8162:exzh3":"Looking at things upside down feels strange.","example:8162:exzh4":"That table is placed upside down.","example:8162:exzh5":"I want to go to an upside-down world."},"8163":{"example:8163:exzh":"I had a new realization.","example:8163:exzh2":"Realizations lead to growth.","example:8163:exzh3":"That realization is important.","example:8163:exzh4":"Realizations are needed in everyday life.","example:8163:exzh5":"A realization can sometimes change your life."},"8164":{"example:8164:exzh":"I'm taking part in a short-term project.","example:8164:exzh2":"Let's set a short-term goal.","example:8164:exzh3":"Short-term work is busy.","example:8164:exzh4":"A short-term contract is a good choice.","example:8164:exzh5":"I'm thinking about short-term study abroad."},"8165":{"example:8165:exzh":"I listened to what the mayor had to say.","example:8165:exzh2":"The mayor is working on local issues.","example:8165:exzh3":"A new mayor was elected.","example:8165:exzh4":"The mayor is the representative of the area.","example:8165:exzh5":"The mayor's job is important."},"8166":{"example:8166:exzh":"There's a whirlpool in the river.","example:8166:exzh2":"I was almost swept away by the whirlpool.","example:8166:exzh3":"The whirlpool is very beautiful.","example:8166:exzh4":"Whirlpools in the sea are scary.","example:8166:exzh5":"That whirlpool is a force of nature."},"8167":{"example:8167:exzh":"He made his debut in music.","example:8167:exzh2":"I'm looking forward to the day of the debut.","example:8167:exzh3":"I can't wait for her debut.","example:8167:exzh4":"We'll hold a party to celebrate the debut.","example:8167:exzh5":"A debut is an important first step."},"8168":{"example:8168:exzh":"Surface temperatures are rising.","example:8168:exzh2":"The grass on the ground is swaying in the wind.","example:8168:exzh3":"Let's observe the condition of the ground surface.","example:8168:exzh4":"Water is pooling on the ground surface.","example:8168:exzh5":"The ground surface reflects sunlight."},"8169":{"example:8169:exzh":"Life can sometimes feel empty.","example:8169:exzh2":"It's hard to fill an empty feeling.","example:8169:exzh3":"He gave an empty smile.","example:8169:exzh4":"I'm thinking about how to spend empty time.","example:8169:exzh5":"When you feel empty, talking with friends helps."},"8170":{"example:8170:exzh":"I couldn't help noticing their sense of discomfort.","example:8170:exzh2":"There's a sense of discomfort between these clothes and my style.","example:8170:exzh3":"Feeling uncomfortable is a natural thing.","example:8170:exzh4":"I want to clear up the sense of discomfort between her and me.","example:8170:exzh5":"If you feel uncomfortable, it's important to talk it out."},"8171":{"example:8171:exzh":"This soil is rich in nutrients.","example:8171:exzh2":"We need soil that's suitable for farming.","example:8171:exzh3":"I learned how to improve the quality of the soil.","example:8171:exzh4":"I water the plants so the soil doesn't dry out.","example:8171:exzh5":"The soil in this area is calcareous."},"8172":{"example:8172:exzh":"This building is extremely solid.","example:8172:exzh2":"His will is firm.","example:8172:exzh3":"A solid foundation is important.","example:8172:exzh4":"She has firm convictions.","example:8172:exzh5":"This team is firmly united."},"8173":{"example:8173:exzh":"This wooden door is old.","example:8173:exzh2":"Please open the door.","example:8173:exzh3":"I installed a new wooden door.","example:8173:exzh4":"The sound of the wooden door bothers me.","example:8173:exzh5":"Someone seems to be on the other side of the wooden door."},"8174":{"example:8174:exzh":"A problem came up.","example:8174:exzh2":"Sometimes new ideas come up.","example:8174:exzh3":"A problem came up, so I'll be late.","example:8174:exzh4":"It's natural for feelings to arise.","example:8174:exzh5":"Anxiety can arise too."},"8175":{"example:8175:exzh":"You can see Venus in the night sky.","example:8175:exzh2":"Venus is a bright star.","example:8175:exzh3":"Venus is close to Earth.","example:8175:exzh4":"I read a book about Venus.","example:8175:exzh5":"Venus is a planet in the solar system."},"8176":{"example:8176:exzh":"He was shot dead.","example:8176:exzh2":"The shooting made the news.","example:8176:exzh3":"Shooting someone is a crime.","example:8176:exzh4":"We're investigating the cause of the shooting.","example:8176:exzh5":"In this country, shootings are a problem."},"8177":{"example:8177:exzh":"You just need to swap this.","example:8177:exzh2":"There's a swap in the schedule.","example:8177:exzh3":"The battery needs to be replaced.","example:8177:exzh4":"He and I swapped roles.","example:8177:exzh5":"The swap took time."},"8178":{"example:8178:exzh":"I value personal relationships.","example:8178:exzh2":"Human support is needed.","example:8178:exzh3":"I want to understand human emotions.","example:8178:exzh4":"It's important to think from a human perspective.","example:8178:exzh5":"Human contact is decreasing."},"8179":{"example:8179:exzh":"There's more and more junk.","example:8179:exzh2":"We have to deal with the junk.","example:8179:exzh3":"He's collecting junk.","example:8179:exzh4":"We should reduce junk.","example:8179:exzh5":"Junk food is bad for your health."},"8180":{"example:8180:exzh":"He went somewhere else.","example:8180:exzh2":"What's he doing somewhere else?","example:8180:exzh3":"I live somewhere else.","example:8180:exzh4":"Try looking somewhere else.","example:8180:exzh5":"This place is different from his other place."},"8181":{"example:8181:exzh":"I'll sort out the arrangements for the event.","example:8181:exzh2":"Arrangements are important.","example:8181:exzh3":"If the arrangements go well, it will succeed.","example:8181:exzh4":"His arrangements were bad.","example:8181:exzh5":"We need to review the arrangements."},"8182":{"example:8182:exzh":"He was chasing the dog around.","example:8182:exzh2":"The kids are chasing the cat around.","example:8182:exzh3":"The suspect is being chased around by the police.","example:8182:exzh4":"Please don't chase animals around.","example:8182:exzh5":"He likes chasing me around."},"8183":{"example:8183:exzh":"Put that away.","example:8183:exzh2":"He put the book away.","example:8183:exzh3":"Put things away properly after you use them.","example:8183:exzh4":"Please decide where to put things away.","example:8183:exzh5":"Don't forget to put it away.","grammar:8183:ex:trans":"Put it away.","grammar:8183:ex:structure":"〜をしまえ","grammar:8183:ex:explain":"This is an imperative sentence. The verb 「しまう（仕舞う）」 is a transitive verb meaning to put away or tidy up; the thing being put away, 「それ」, is marked with 「を」, and 「しまえ」 is its imperative form (godan verb: u → e). Note the important distinction: here 「しまう」 is the main verb meaning to put away, different from the auxiliary verb 「〜てしまう」, which shows completion or regret. The imperative form has a strong tone and is often used by seniors speaking to juniors.","grammar:8183:ex:words:0:zh":"that","grammar:8183:ex:words:0:pos":"pronoun","grammar:8183:ex:words:1:zh":"(object marker)","grammar:8183:ex:words:1:pos":"particle","grammar:8183:ex:words:2:zh":"put away (command)","grammar:8183:ex:words:2:note":"しまえ","grammar:8183:ex:words:2:pos":"verb","grammar:8183:ex:points:0":"❗しまう（仕舞う）: to put away, to tidy up (transitive verb); しまえ = put it away (imperative form); note the contrast with the auxiliary verb 「〜てしまう」 (completion / regret).","grammar:8183:ex:points:1":"しまう: to put away.","grammar:8183:ex2:trans":"He put the book away.","grammar:8183:ex2:structure":"〜をしまった","grammar:8183:ex2:words:0:zh":"he","grammar:8183:ex2:words:0:note":"かれ","grammar:8183:ex2:words:0:pos":"pronoun","grammar:8183:ex2:words:1:zh":"(topic)","grammar:8183:ex2:words:1:pos":"particle","grammar:8183:ex2:words:2:zh":"book","grammar:8183:ex2:words:2:note":"ほん","grammar:8183:ex2:words:2:pos":"noun","grammar:8183:ex2:words:3:zh":"(object marker)","grammar:8183:ex2:words:3:pos":"particle","grammar:8183:ex2:words:4:zh":"put away","grammar:8183:ex2:words:4:note":"しまった","grammar:8183:ex2:words:4:pos":"verb","grammar:8183:ex2:points:0":"❗本をしまう: to put the book away (here it is the main verb meaning to tidy up, not an auxiliary verb).","grammar:8183:ex2:points:1":"本をしまう: to put books away.","grammar:8183:ex3:trans":"Put away the things you've used properly.","grammar:8183:ex3:structure":"〜はちゃんとしまえ","grammar:8183:ex3:words:0:zh":"used","grammar:8183:ex3:words:0:note":"つかった","grammar:8183:ex3:words:0:pos":"verb","grammar:8183:ex3:words:1:zh":"things","grammar:8183:ex3:words:1:pos":"noun","grammar:8183:ex3:words:2:zh":"(topic)","grammar:8183:ex3:words:2:pos":"particle","grammar:8183:ex3:words:3:zh":"well","grammar:8183:ex3:words:3:pos":"adverb","grammar:8183:ex3:words:4:zh":"put away (command)","grammar:8183:ex3:words:4:note":"しまえ","grammar:8183:ex3:words:4:pos":"verb","grammar:8183:ex3:points:0":"❗ちゃんとしまう: to put away properly; 使ったもの = the things you've used.","grammar:8183:ex3:points:1":"ちゃんとしまえ: put it away properly.","grammar:8183:ex4:trans":"Please decide where to keep it.","grammar:8183:ex4:structure":"しまう場所を決めてください","grammar:8183:ex4:words:0:zh":"to put away, to store","grammar:8183:ex4:words:0:note":"しまう","grammar:8183:ex4:words:0:pos":"verb","grammar:8183:ex4:words:1:zh":"place","grammar:8183:ex4:words:1:note":"ばしょ","grammar:8183:ex4:words:1:pos":"noun","grammar:8183:ex4:words:2:zh":"(object marker)","grammar:8183:ex4:words:2:pos":"particle","grammar:8183:ex4:words:3:zh":"decide","grammar:8183:ex4:words:3:note":"きめて","grammar:8183:ex4:words:3:pos":"verb","grammar:8183:ex4:words:4:zh":"please","grammar:8183:ex4:words:4:pos":"auxiliary verb","grammar:8183:ex4:points:0":"❗しまう場所: a place to put things away (pre-noun modification); 決める = to decide.","grammar:8183:ex4:points:1":"しまう場所: a place to put things away.","grammar:8183:ex5:trans":"Don't forget to put it away.","grammar:8183:ex5:structure":"しまうのを忘れないで","grammar:8183:ex5:words:0:zh":"put away","grammar:8183:ex5:words:0:note":"しまう","grammar:8183:ex5:words:0:pos":"verb","grammar:8183:ex5:words:1:zh":"(nominalizer)","grammar:8183:ex5:words:1:pos":"particle","grammar:8183:ex5:words:2:zh":"(object marker)","grammar:8183:ex5:words:2:pos":"particle","grammar:8183:ex5:words:3:zh":"don't forget","grammar:8183:ex5:words:3:note":"わすれないで","grammar:8183:ex5:words:3:pos":"verb","grammar:8183:ex5:points:0":"❗しまうのを忘れないで: don't forget to put it away; 〜のを忘れないで = don't forget to do…","grammar:8183:ex5:points:1":"しまうのを忘れる: to forget to put it away."},"8184":{"example:8184:exzh":"He uses a prosthetic leg.","example:8184:exzh2":"Prosthetic leg technology is advancing.","example:8184:exzh3":"I'm researching prosthetic legs.","example:8184:exzh4":"Fitting a prosthetic leg is difficult.","example:8184:exzh5":"I need a new prosthetic leg."},"8185":{"example:8185:exzh":"I'll take handwritten notes.","example:8185:exzh2":"I like handwriting.","example:8185:exzh3":"I got a handwritten signature.","example:8185:exzh4":"He wrote a letter by hand.","example:8185:exzh5":"Handwriting shows personality."},"8186":{"example:8186:exzh":"Who's in charge of this project?","example:8186:exzh2":"I'm doing the work I'm in charge of.","example:8186:exzh3":"He works as the person in charge.","example:8186:exzh4":"I talked with the person in charge.","example:8186:exzh5":"My assigned work keeps increasing."},"8187":{"example:8187:exzh":"I watched the weather forecast.","example:8187:exzh2":"Tomorrow's forecast is rain.","example:8187:exzh3":"The forecast was wrong.","example:8187:exzh4":"The weather agency is issuing a forecast.","example:8187:exzh5":"There's a forecast for snow."},"8188":{"example:8188:exzh":"Debt collection is harsh.","example:8188:exzh2":"Collecting taxes is important.","example:8188:exzh3":"He works as a debt collector.","example:8188:exzh4":"Debt collection is carried out based on the law.","example:8188:exzh5":"Please tell me how the collection is done."},"8189":{"example:8189:exzh":"They share the pain in their hearts.","example:8189:exzh2":"I'm suffering from inner conflict.","example:8189:exzh3":"I want to convey the feelings in my heart.","example:8189:exzh4":"I open up about the unease in my heart.","example:8189:exzh5":"She keeps a secret in her heart."},"8190":{"example:8190:exzh":"I'll stop off somewhere on my way home.","example:8190:exzh2":"The detour to the station was fun.","example:8190:exzh3":"Stopping off somewhere on the way takes more time.","example:8190:exzh4":"Sometimes taking a detour is nice too.","example:8190:exzh5":"Even though we took a detour, the scenery was beautiful."},"8192":{"example:8192:exzh":"Something might have fallen off.","example:8192:exzh2":"I need to replace the part that fell off.","example:8192:exzh3":"I'm worried about accidents caused by parts falling off.","example:8192:exzh4":"Parts often come off.","example:8192:exzh5":"This device comes loose easily."},"8193":{"example:8193:exzh":"There's a parking lot in one corner.","example:8193:exzh2":"We had a picnic in a corner of the park.","example:8193:exzh3":"That corner is quiet.","example:8193:exzh4":"There's a small shop in the corner.","example:8193:exzh5":"There's a bookshelf in one corner of this room."},"8194":{"example:8194:exzh":"Velociraptor is a kind of dinosaur.","example:8194:exzh2":"Velociraptors run fast.","example:8194:exzh3":"I like the velociraptors that appear in movies.","example:8194:exzh4":"The velociraptor's skeleton is unique.","example:8194:exzh5":"Velociraptors are carnivorous."},"8195":{"example:8195:exzh":"Use a transformer to make new shapes.","example:8195:exzh2":"Transformers are popular with children.","example:8195:exzh3":"This transformer has a special feature.","example:8195:exzh4":"Tell me how to play with the transformer.","example:8195:exzh5":"Transformers nurture creativity."},"8198":{"example:8198:exzh":"His life is fulfilling.","example:8198:exzh2":"I had a fulfilling time.","example:8198:exzh3":"This job gives me a sense of fulfillment.","example:8198:exzh4":"She leads a fulfilling daily life.","example:8198:exzh5":"I'm aiming for a fulfilling life."},"8199":{"example:8199:exzh":"I'm worried about him.","example:8199:exzh2":"I'm worried about the exam results.","example:8199:exzh3":"I have lots of things to worry about.","example:8199:exzh4":"I was so worried that I couldn't sleep.","example:8199:exzh5":"I'm worried about health."}};